mapper.select:
SELECT s.id, s.system_code, s.login_name, s.user_name, s.signature_action, s.signature_data, s.signature_type, s.remark, s.create_time, m.name as systemName, s.success FROM bp_signature_log s LEFT JOIN bp_menu m ON m.id = s.system_code WHERE m.is_deleted = 0
and s.user_name like concat('%',#{userName},'%')
and s.create_time between #{startTimeDate} and #{endTimeDate}
and s.system_code = #{systemCode}
order by s.create_time desc
